// [MEDIUM_PRIORITY] UX_POLISH: Empty state handled
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.proactiveimport timber.log.Timberimport java.time.DayOfWeekimport java.time.Durationimport java.time.LocalDateimport java.time.LocalTimeimport java.time.ZoneIdimport java.util.concurrent.atomic.AtomicReference/** * NOUS — Habit Tracker (§20 v2 Fix #7 — Behavioral Proactive). * * v1 flaw: rule-based proactive engine (calendar, battery, missed calls) = * "alarm clock" — fires the same triggers regardless of user behavior. * * v2 fix: detect user habits from episodic memory patterns. If the user * does the same thing 5+ days in a row at the same time, NOUS can * proactively suggest it. * * ## Examples (§20) * *  - "User opens camera at 8 AM daily" → "Shall I open your camera?" *  - "User calls mom every Sunday 7 PM" → "Want me to call mom?" *  - "User checks weather before leaving" → "It's 24°C, no rain." * * ## Algorithm (§20) * *  1. Recall recent memories tagged "daily routine" from the Memory Module. *  2. Find recurring patterns — same action, same time-of-day (±30 min), *     on ≥ [Config.minRepetitionDays] distinct days. *  3. Score each pattern by [confidence] = (matching days / total observed days). *  4. Filter: only suggest habits with confidence > [Config.confidenceThreshold]. *  5. Don't re-suggest a habit on the same day it was already suggested or *     already performed by the user. * * ## Testability * * The Memory Module interface ([MemoryInterface]) is injected — tests use * a fake. Pattern detection ([findRecurringPatterns]) is a pure function * of (memories, config) → testable without Android. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§20 HabitTracker (Behavioral Proactive) — v2 Fix #7</a> */class HabitTracker(    private val memory: MemoryInterface,    private val config: Config = Config(),) {    /**     * Configuration for the habit tracker.     *     * @param minRepetitionDays   minimum distinct days for a pattern to qualify     *                             as a habit (default 5 per §20).     * @param confidenceThreshold habits with confidence below this are filtered     *                             out (default 0.7 per §20).     * @param timeWindowMinutes   how much time variance counts as "same time"     *                             (±30 min default — user opens camera at     *                             7:55, 8:05, 8:12 → all "8 AM").     * @param reSuggestionCooldownDays  don't re-suggest a habit for this many     *                             days after it was last suggested (default 1     *                             = don't suggest twice in one day).     */    data class Config(        val minRepetitionDays: Int = DEFAULT_MIN_REPETITION_DAYS,        val confidenceThreshold: Float = DEFAULT_CONFIDENCE_THRESHOLD,        val timeWindowMinutes: Int = DEFAULT_TIME_WINDOW_MINUTES,        val reSuggestionCooldownDays: Int = DEFAULT_RE_SUGGESTION_COOLDOWN_DAYS,    ) {        init {            require(minRepetitionDays in 1..30) { "minRepetitionDays must be 1..30" }            require(confidenceThreshold in 0f..1f) { "confidenceThreshold must be in [0,1]" }            require(timeWindowMinutes in 1..240) { "timeWindowMinutes must be 1..240" }            require(reSuggestionCooldownDays in 0..30) { "reSuggestionCooldownDays must be 0..30" }        }        companion object {            const val DEFAULT_MIN_REPETITION_DAYS = 5            const val DEFAULT_CONFIDENCE_THRESHOLD = 0.7f            const val DEFAULT_TIME_WINDOW_MINUTES = 30            const val DEFAULT_RE_SUGGESTION_COOLDOWN_DAYS = 1        }    }    /** Tracks the last-suggestion date per habit description (for cooldown). */    private val lastSuggested = mutableMapOf<String, LocalDate>()    /**     * Detect habits from recent memories.     *     * @return habits sorted by confidence desc, filtered by [Config.confidenceThreshold].     */    suspend fun detectHabits(): List<Habit> {        val recentMemories = runCatching { memory.recall("daily routine", 50) }            .onFailure { Timber.tag(TAG).w("Memory recall failed.", it) }            .getOrDefault(emptyList())        if (recentMemories.isEmpty()) return emptyList()        val patterns = findRecurringPatterns(recentMemories)        return patterns            .map { pattern ->                Habit(                    description = pattern.description,                    triggerTime = pattern.averageTime,                    triggerDays = pattern.daysOfWeek,                    confidence = pattern.confidence,                    lastSuggested = lastSuggested[pattern.description],                )            }            .filter { it.confidence > config.confidenceThreshold }            .sortedByDescending { it.confidence }    }    /**     * Suggest a habit proactively.     *     * @return true if the suggestion was made, false if suppressed (cooldown     *         or user already did the action today).     */    suspend fun suggestHabit(habit: Habit, today: LocalDate = LocalDate.now()): Boolean {        // 1. Don't suggest if already suggested today.        if (habit.lastSuggested == today) return false        // 2. Don't suggest if user already did the action today.        if (userAlreadyDidActionToday(habit, today)) {            Timber.tag(TAG).d("User already did '${habit.description}' today — not suggesting.")            return false        }        // 3. Record the suggestion.        lastSuggested[habit.description] = today        // The actual TTS speak is done by the caller (ProactiveEngine) — this        // method just decides whether the suggestion should fire.        return true    }    /**     * Find recurring patterns in episodic memories.     *     * Pure function — testable without the Memory Module.     *     * @param memories recent episodic memories with action + timestamp.     * @return patterns that meet [Config.minRepetitionDays] threshold.     */    internal fun findRecurringPatterns(memories: List<EpisodicMemory>): List<HabitPattern> {        // Group memories by action description.        val byAction = memories.groupBy { it.actionDescription }        val patterns = mutableListOf<HabitPattern>()        for ((action, actionMemories) in byAction) {            if (actionMemories.size < config.minRepetitionDays) continue            // Bucket by time-of-day window (e.g. 8:00, 8:30, 9:00).            val windowMinutes = config.timeWindowMinutes            val buckets = mutableMapOf<Int, MutableList<EpisodicMemory>>()            for (m in actionMemories) {                val bucket = (m.timestamp.hour * 60 + m.timestamp.minute) / windowMinutes                buckets.getOrPut(bucket) { mutableListOf() }.add(m)            }            // Find the bucket with the most distinct days.            val bestBucket = buckets.maxByOrNull { it.value.map { m -> m.date }.distinct().size }                ?: continue            val distinctDays = bestBucket.value.map { it.date }.distinct()            if (distinctDays.size < config.minRepetitionDays) continue            // Confidence = distinct days / total observation window.            val totalDays = (memories.maxOf { it.date }.toEpochDay() -                memories.minOf { it.date }.toEpochDay() + 1).toInt().coerceAtLeast(1)            val confidence = distinctDays.size.toFloat() / totalDays            // Average time across the bucket.            val avgMinutes = bestBucket.value                .map { it.timestamp.hour * 60 + it.timestamp.minute }                .average().toInt()            val avgTime = LocalTime.of(avgMinutes / 60, avgMinutes % 60)            // Days of week the pattern fires on.            val daysOfWeek = distinctDays.map { it.dayOfWeek }.distinct()            patterns.add(HabitPattern(                description = action,                averageTime = avgTime,                daysOfWeek = daysOfWeek,                confidence = confidence.coerceIn(0f, 1f),                observationCount = distinctDays.size,            ))        }        return patterns    }    /** Check if the user already performed [habit.description] today. */    private suspend fun userAlreadyDidActionToday(habit: Habit, today: LocalDate): Boolean {        val todayMemories = runCatching { memory.recall(habit.description, 10) }            .getOrDefault(emptyList())        return todayMemories.any { it.date == today }    }    private companion object {        private const val TAG = "HabitTracker"    }}// ──────────────────────────────────────────────────────────────────────────/** One detected habit. */data class Habit(    val description: String,    val triggerTime: LocalTime,    val triggerDays: List<DayOfWeek>,    val confidence: Float,    val lastSuggested: LocalDate? = null,) {    init {        require(description.isNotBlank()) { "description must not be blank" }        require(confidence in 0f..1f) { "confidence must be in [0,1]" }    }}// ──────────────────────────────────────────────────────────────────────────/** Internal pattern found during habit detection. */internal data class HabitPattern(    val description: String,    val averageTime: LocalTime,    val daysOfWeek: List<DayOfWeek>,    val confidence: Float,    val observationCount: Int,)// ──────────────────────────────────────────────────────────────────────────/** * One episodic memory entry from the Memory Module. * * @param actionDescription  what the user did (e.g. "open_camera", "call_mom"). * @param timestamp          when (local time) — used for time-of-day pattern. * @param date               which day — used for distinct-day counting. */data class EpisodicMemory(    val actionDescription: String,    val timestamp: LocalTime,    val date: LocalDate,)// ──────────────────────────────────────────────────────────────────────────/** * Memory Module interface (real impl in :feature:memory). * * Used by [HabitTracker] to recall recent episodic memories. Tests inject * a fake. */interface MemoryInterface {    /**     * Recall recent memories matching [query].     *     * @param query search query (e.g. "daily routine", "open_camera").     * @param k     max memories to return.     * @return memories, most recent first.     */    suspend fun recall(query: String, k: Int): List<EpisodicMemory>}